INSERT INTO `products` (`product_id`, `category_id`, `product_name`, `product_type`, `description`, `care_instructions`, `image`, `created_at`) VALUES ('64', '10', 'Textured Fiber Clay Planter', 'Pot', 'Architectural ribbed fluted fiber-clay planter with horizontal textural relief and organic stone tactile charm.', 'Dust with a soft brush. Excellent insulation protects plant root systems from heat and cold.', 'pots/fiberglass-fiber-clay/textured/textured-fiber-clay-planter-sand.jpeg', '2026-09-13 21:25:53');
INSERT INTO `products` (`product_id`, `category_id`, `product_name`, `product_type`, `description`, `care_instructions`, `image`, `created_at`) VALUES ('65', '11', 'Minimal Cement Pot', 'Pot', 'Cast concrete cylindrical planter with authentic industrial pore texture and raw urban minimalist beauty.', 'Sealed to repel moisture absorption. Wipe clean with soft damp cloth. Felt feet recommended on sensitive tables.', 'pots/cement-stone/minimal/minimal-cement-pot-natural-gray.jpeg', '2026-09-13 21:25:54');
INSERT INTO `products` (`product_id`, `category_id`, `product_name`, `product_type`, `description`, `care_instructions`, `image`, `created_at`) VALUES ('66', '11', 'Stone Texture Planter', 'Pot', 'Rugged chiseled cast stone planter with natural mineral speckles and durable wind-resistant heavy walls.', 'Rinse with clean water. Supremely heavy and storm-resistant for heavy indoor and patio foliage.', 'pots/cement-stone/stone-texture/stone-texture-planter-sandstone.jpeg', '2026-09-13 21:25:55');
INSERT INTO `products` (`product_id`, `category_id`, `product_name`, `product_type`, `description`, `care_instructions`, `image`, `created_at`) VALUES ('67', '11', 'Geometric Concrete Planter', 'Pot', 'Sculptural faceted concrete plant pot featuring crisp polygonal angles and modern architectural geometry.', 'Wipe with microfiber. Heavy base provides complete tip-proof stability for tall plants.', 'pots/cement-stone/geometric/geometric-concrete-planter-charcoal.jpeg', '2026-09-13 21:25:55');
INSERT INTO `products` (`product_id`, `category_id`, `product_name`, `product_type`, `description`, `care_instructions`, `image`, `created_at`) VALUES ('68', '11', 'Heavy Cement Bowl Planter', 'Pot', 'Low-profile wide concrete bowl planter designed for succulent dish gardens, bonsai, or cascading tabletop arrangements.', 'Hand clean with mild soap. Sealed interior protects surfaces while retaining plant moisture.', 'pots/cement-stone/heavy-bowl/heavy-cement-bowl-planter-natural-gray.jpeg', '2026-09-13 21:25:56');
